package main

import (
	"encoding/json"
	"fmt"
	"log"
	"node"
)

var kv node.LinKV

func init() {
	kv = node.NewLinKV("lin-kv")
}

type AppendRequest struct {
	Journal string `json:"journal"`
	Entry   int    `json:"entry"`
}

type FetchRequest struct {
	Positions map[string]int `json:"positions"`
}

type BookmarkRequest struct {
	Positions map[string]int `json:"positions"`
}

type BookmarksRequest struct {
	Journals []string `json:"journals"`
}

func main() {
	node.NewNode(node.Config{
		InitOnce: true,
	}.Handle(func(ctx node.Context) {
		switch ctx.Message().Type {
		case "init":
			return
		case "append":
			handleAppend(ctx)
		case "fetch":
			handleFetch(ctx)
		case "bookmark":
			handleBookmark(ctx)
		case "bookmarks":
			handleBookmarks(ctx)
		}
	}))
}

func handleAppend(ctx node.Context) {
	var req AppendRequest
	if err := json.Unmarshal([]byte(ctx.Message().Body), &req); err != nil {
		log.Printf("Error unmarshaling append: %v", err)
		return
	}

	newPos, _ := getMaxPosition(req.Journal) + 1

	// Store entry value and position together
	entryData := fmt.Sprintf("%d,%d", req.Entry, newPos)
	kv.Write(node.Context{}, key(req.Journal, newPos), entryData)

	ctx.ReplyWith(ctx.Message(), node.NewAppended(
		node.Map{"msg_id": float64(ctx.Message()["msg_id"])}))
}

func getMaxPosition(journal string) (int, error) {
	maxPosKey := maxPosKey(journal)
	val, err := kv.Read(node.Context{}, maxPosKey, false)
	if err != nil || val == "nil" {
		return -1, nil
	}

	pos, _ := parseInt(val)
	if pos == -1 {
		return -1, nil
	}
	return pos, nil
}

func maxPosKey(journal string) string {
	return fmt.Sprintf("max_pos:%s", journal)
}

func key(journal string, pos int) string {
	return fmt.Sprintf("%s:%d", journal, pos)
}

func handleFetch(ctx node.Context) {
	var req FetchRequest
	if err := json.Unmarshal([]byte(ctx.Message().Body), &req); err != nil {
		log.Printf("Error unmarshaling fetch: %v", err)
		return
	}

	result := make(map[string][][]int)

	for journal, pos := range req.Positions {
		entries := fetchFromJournal(journal, pos)
		result[journal] = entries
	}

	ctx.ReplyWith(ctx.Message(), node.NewFetched(
		node.Map{"msg_id": float64(ctx.Message()["msg_id"]), "entries": result}))
}

func fetchFromJournal(journal string, startPos int) [][]int {
	entries := make([][]int, 0)
	currentPos := startPos

	for {
		entryKey := key(journal, currentPos)
		val, exists := kv.Read(node.Context{}, entryKey, false)

		if !exists || val == "nil" {
			break
		}

		data := parseEntryData(val)
		pos, entryVal := data

		entries = append(entries, []int{pos, entryVal})
		currentPos++
	}

	return entries
}

func parseEntryData(data string) (int, int) {
	parts := splitString(data, ',')
	if len(parts) != 2 {
		return -1, -1
	}
	pos, _ := strconv.Atoi(parts[0])
	entryVal, _ := strconv.Atoi(parts[1])
	return pos, entryVal
}

func handleBookmark(ctx node.Context) {
	var req BookmarkRequest
	if err := json.Unmarshal([]byte(ctx.Message().Body), &req); err != nil {
		log.Printf("Error unmarshaling bookmark: %v", err)
		return
	}

	result := make(map[string]int)

	for journal, pos := range req.Positions {
		entryKey := key(journal, pos)
		val, exists := kv.Read(node.Context{}, entryKey, false)

		if exists && val != "nil" {
			data := parseEntryData(val)
			result[journal] = data[0]

			kv.Write(node.Context{}, bookmarkKey(journal), "true")
		}
	}

	ctx.ReplyWith(ctx.Message(), node.NewBookmarked(
		node.Map{"msg_id": float64(ctx.Message()["msg_id"]), "in_reply_to": ctx.Message()["msg_id"]}))
}

func handleBookmarks(ctx node.Context) {
	var req BookmarksRequest
	if err := json.Unmarshal([]byte(ctx.Message().Body), &req); err != nil {
		log.Printf("Error unmarshaling bookmarks: %v", err)
		return
	}

	result := make(map[string]int)

	for _, journal := range req.Journals {
		bkKey := bookmarkKey(journal)
		val, exists := kv.Read(node.Context{}, bkKey, false)

		if exists && val == "true" {
			maxPos, _ := getMaxPosition(journal)
			result[journal] = maxPos
		}
	}

	ctx.ReplyWith(ctx.Message(), node.NewBookmarksAre(
		node.Map{"msg_id": float64(ctx.Message()["msg_id"]), "positions": result}))
}

func bookmarkKey(journal string) string {
	return fmt.Sprintf("bookmark:%s", journal)
}

